import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long x = nextLong(), y = nextLong();
        long[] a = new long[n];
        long mx = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            mx = Math.max(mx, a[i]);
        }
        long extra = x - y, lo = 0, hi = (mx + y - 1) / y;
        // t operations give every task t*y; each main pick adds extra = x - y more.
        while (lo < hi) {
            long t = (lo + hi) / 2, need = 0;
            for (long v : a) {
                long rem = v - t * y;
                if (rem > 0) need += (rem + extra - 1) / extra;
            }
            if (need <= t) hi = t;
            else lo = t + 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	x, y := nextInt(), nextInt()
	a := make([]int64, n)
	var mx int64
	for i := range a {
		a[i] = nextInt()
		mx = max(mx, a[i])
	}
	extra, lo, hi := x-y, int64(0), (mx+y-1)/y
	// t operations give every task t*y; each main pick adds extra = x - y more.
	for lo < hi {
		t := (lo + hi) / 2
		var need int64
		for _, v := range a {
			if rem := v - t*y; rem > 0 {
				need += (rem + extra - 1) / extra
			}
		}
		if need <= t {
			hi = t
		} else {
			lo = t + 1
		}
	}
	fmt.Println(lo)
}
